package com.orderflow.orderservice.messaging; import com.orderflow.contracts.*; import com.orderflow.orderservice.domain.*; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Component; import java.time.Instant;
@Component public class OrderSagaListener { private final OrderRepository orders; private final SagaHistoryRepository history; public OrderSagaListener(OrderRepository o,SagaHistoryRepository h){orders=o;history=h;} @KafkaListener(topics=Topics.ORDER_NOTIFY,groupId="order-service") public void on(SagaEvent e){ orders.findById(e.orderId()).ifPresent(o->{o.status=e.status()==SagaStatus.FINISHED?"COMPLETED":"CANCELLED";orders.save(o);}); SagaHistory h=history.findByOrderId(e.orderId()).orElseGet(SagaHistory::new); h.orderId=e.orderId();h.transactionId=e.transactionId();h.status=e.status().name();h.events.add(e.createdAt()+" | "+e.source()+" | "+e.status()+" | "+e.message());h.updatedAt=Instant.now();history.save(h); } }
